(18, 'MAIL_TO_AUTHOR', 'Send Email to Author', 'New email from user', NULL, '<div>Username:&nbsp;{{username}}</div><div><span style=\"color: var(--bs-body-color); font-size: 1rem; text-align: var(--bs-body-text-align);\">Email:&nbsp;{{email}}</span><br></div><div>Message: {{message}}</div>', 'New sms from: {{username}}', NULL, '{\"username\":\"Username\",\"email\":\"Email\", \"message\": \"Message from user\"}', 1, NULL, NULL, 0, NULL, 0, NULL, '2023-12-11 05:40:06'),
(19, 'REFUND_REJECTED', 'Refund Request - Rejected', 'Refund Request Rejected', NULL, 'Your refund request is rejected for the purchase code of&nbsp;{{purchase_code}}', '{{amount}} {{site_currency}} credited in your account. Your Current Balance {{post_balance}} {{site_currency}} . Transaction: #{{trx}}. Admin note is \"{{remark}}\"', NULL, '{\"purchase_code\":\"Purchase Code of the item\", \"message\": \"Message for the author\", \"buyer\": \"Buyer\'s username\", \"author\":\"Author\'s username\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2023-12-04 07:01:45'),
(20, 'COMMENTED', 'Commented', 'New Comment on Your Product', NULL, 'Hey&nbsp;{{author}},&nbsp;<div>{{username}} commented on your item&nbsp;<b>{{product_name}} .</b></div><div><b>Comment content</b>:&nbsp;{{comment}}</div><div><b>Reply URL:&nbsp;</b><span style=\"text-align: var(--bs-body-text-align);\"><font color=\"#212529\">{{url}}</font></span></div>', 'Hey {{author}}, \r\n{{username}} commented on your item {{product_name}} .\r\nComment content: {{comment}}\r\nReply URL: {{url}}', NULL, '{\"comment\":\"Comment body\", \"author\": \"Author\'s username\", \"comment_user_mail\": \"Comment user email\", \"product_name\": \"Product\'s name\", \"username\": \"Comment username\", \"url\": \"URL to view the comment\"}', 1, NULL, NULL, 1, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 12:37:56'),
(21, 'REFUND_APPROVED', 'Refund Request - Approved', 'Refund Request Approved', NULL, 'Your Refund Request Approved.<div>Purchase Code:&nbsp;{{purchase_code}}</div><div>Amount:&nbsp;{{amount}}</div><div>Amount added to your balance.</div>', '{{amount}} {{site_currency}} credited in your account. Your Current Balance {{post_balance}} {{site_currency}} . Transaction: #{{trx}}. Admin note is \"{{remark}}\"', NULL, '{\"purchase_code\":\"Purchase Code of the item\", \"amount\" :\"Amount added to balance\", \"message\": \"Message for the author\", \"buyer\": \"Buyer\'s username\", \"author\": \"Author\'s username\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2023-12-17 07:02:54'),
(22, 'PAYMENT_VIA_ACCOUNT', 'Payment via Account Balance - Subtracted', 'Your Account has been Debited', NULL, '<div style=\"font-family: Montserrat, sans-serif;\">{{amount}} {{site_currency}} has been subtracted from your account .</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><div style=\"font-family: Montserrat, sans-serif;\">Transaction Number : {{trx}}</div><div style=\"font-family: Montserrat, sans-serif;\"><br></div><span style=\"color: rgb(33, 37, 41); font-family: Montserrat, sans-serif;\">Your Current Balance is :&nbsp;</span><font style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\">{{post_balance}}&nbsp; {{site_currency}}</span></font><br><div><font style=\"font-family: Montserrat, sans-serif;\"><span style=\"font-weight: bolder;\"><br></span></font></div><div>Admin Note: {{remark}}</div>', '{{amount}} {{site_currency}} debited from your account. Your Current Balance {{post_balance}} {{site_currency}} . Transaction: #{{trx}}. Admin Note is {{remark}}', NULL, '{\"trx\":\"Transaction number for the action\",\"amount\":\"Amount inserted by the admin\",\"remark\":\"Remark inserted by the admin\",\"post_balance\":\"Balance of the user after this transaction\"}', 1, NULL, NULL, 1, NULL, 0, '2021-11-03 12:00:00', '2022-04-03 02:24:11'),
(23, 'REVIEWER_BANNED', 'Reviewer Banned', 'You are banned!', NULL, '<div style=\"text-align: center;\"><b style=\"text-align: var(--bs-body-text-align);\"><font size=\"6\" style=\"\" color=\"#cc3399\">You are banned:</font></b></div><div><br></div><div>Reason:&nbsp;</div><div>{{reason}}<br></div>', 'Reason: \r\n{{reason}}', NULL, '{\"reason\":\"The reason for ban\"}\r\n', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2023-12-19 08:59:49'),
(24, 'REVIEW_NOTIFICATION', 'Item Review Notification', 'Your Item Reviewed', NULL, 'The item you submitted to the&nbsp;{{site_name}} is reviewed by our reviewer.<div>Item Status:&nbsp;{{status}}</div><div>Review Message:&nbsp;{{message}}</div><div><br></div>', 'asdfasdf', NULL, '{\"status\":\"Status of the item\",\"message\":\"Review message by the reviewer\"}', 1, NULL, NULL, 1, NULL, 0, '2021-11-03 12:00:00', '2023-12-19 09:24:01'),
(25, 'BUYER_REVIEW', 'Buyer Review', 'Your item reviewed by buyer', NULL, 'Your item got a new review in the category of :&nbsp;{{review_category}}<div>View the details here:&nbsp;{{link}}</div>', 'asdfasdf', NULL, '{\"buyer\" : \"Buyer username\", \"purchase_code\":\"Purchase code of the item\",\"review\":\"Review message by the buyer\",\"rating\":\"Rating of the review\",\"review_category\":\"In which category the rating submitted\", \"link\" : \"Link of the review\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2023-12-19 09:36:18'),
(27, 'NEW_REFUND_REQUEST', 'Refund Request - New', 'New Refund Request', NULL, NULL, NULL, NULL, '{\"buyer\": \"Buyer username\", \"purchase_code\":\"Purchase code of the item\",\"reason\":\"Reason Fore Refund\", \"refundable_amount\": \"Refundable amount\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2023-12-19 09:36:18'),
(28, 'PRODUCT_APPROVED', 'Product Approved', 'Your product has been approved', NULL, '<span style=\"color: rgb(33, 37, 41);\">Hello&nbsp;{{author}},</span><div>Your<span style=\"font-weight: bolder;\"> {{product_name}}&nbsp;</span>, in&nbsp;{{product_category}} is approved at {{approved_time}}.&nbsp;<br></div><div>Reviewer message:&nbsp;{{message}}</div>', 'Hello {{author}},\r\nYour {{product_name}} , in {{product_category}} is approved at {{approved_time}}. \r\nReviewer message: {{message}}', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\",\"approved_time\":\"Time when approved\",\"url\":\"URL of approved product\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 12:40:17'),
(29, 'PRODUCT_SOFT_REJECTED', 'Product Soft Reject', 'Product soft rejected', NULL, '<span style=\"color: rgb(33, 37, 41);\">Hello&nbsp;{{author}},</span><div>Your<span style=\"font-weight: bolder;\">&nbsp;</span><b>{{product_name}}&nbsp;</b>, in&nbsp;<b>{{product_category}} </b>is soft rejected at {{review_time}}.&nbsp; You can edit the item from the following link:&nbsp;{{edit_url}}<br></div><div>Reviewer message:&nbsp;{{message}}</div>', 'Hello {{author}},\r\nYour {{product_name}} , in {{product_category}} is soft rejected at {{review_time}}.  You can edit the item from the following link: {{edit_url}}\r\nReviewer message: {{message}}', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\", \"product_category\": \"Product Category\",\"review_time\":\"Time when reviewd\",\"edit_url\":\"URL for re-submission\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 11:56:03'),
(30, 'PRODUCT_HARD_REJECTED', 'Product Hard Reject', 'Product hard rejected', NULL, '<span style=\"color: rgb(33, 37, 41);\">Hello&nbsp;{{author}},</span><div>Your<span style=\"font-weight: bolder;\">&nbsp;</span><span style=\"font-weight: bolder;\">{{product_name}}&nbsp;</span>, in&nbsp;<span style=\"font-weight: bolder;\">{{product_category}}&nbsp;</span>is hard rejected at {{review_time}}.&nbsp;&nbsp;<br></div><div>Reviewer message:&nbsp;{{message}}</div>', 'Hello {{author}},\r\nYour {{product_name}} , in {{product_category}} is hard rejected at {{review_time}}.  \r\nReviewer message: {{message}}', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\", \"product_category\": \"Product Category\",\"review_time\":\"Time when reviewd\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 11:56:59'),
(31, 'PRODUCT_DOWN', 'Product Down', 'Your Product is temporarily down', NULL, '<span style=\"color: rgb(33, 37, 41);\">Hello&nbsp;{{author}},</span><div>Your<span style=\"font-weight: bolder;\">&nbsp;{{product_name}}&nbsp;</span>, in&nbsp;{{product_category}} is down at {{review_time}}.&nbsp; You can edit&nbsp; the product from here: {{edit_url}} .&nbsp;<br></div><div>Reviewer message:&nbsp;{{message}}</div>', 'Hello {{author}},\r\nYour {{product_name}} , in {{product_category}} is down at {{review_time}}. \r\nReviewer message: {{message}}', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\", \"product_category\": \"Product Category\",\"review_time\":\"Time when reviewd\", \"edit_url\": \"Edit URL\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 11:30:42'),
(32, 'PRODUCT_PERMANENT_DOWN', 'Product Permanent Down', 'Your Product is permanently down', NULL, '', '', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\", \"product_category\": \"Product Category\",\"review_time\":\"Time when reviewd\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2022-04-03 02:18:28'),
(33, 'PRODUCT_UPDATE_REJECTED', 'Product update rejected', 'Your update rejected', NULL, '<span style=\"color: rgb(33, 37, 41);\">Hello&nbsp;{{author}},</span><div>Your<span style=\"font-weight: bolder;\">&nbsp;</span><span style=\"font-weight: bolder;\">{{product_name}}&nbsp;</span>, in&nbsp;<span style=\"font-weight: bolder;\">{{product_category}}</span>\'s update is rejected at {{review_time}}.&nbsp; You can edit the item from this link:&nbsp;{{edit_url}}&nbsp;<br></div><div>Reviewer message:&nbsp;{{message}}</div>', 'Hello {{author}},\r\nYour {{product_name}} , in {{product_category}}\'s update is rejected at {{review_time}}.  You can edit the item from this link: {{edit_url}} \r\nReviewer message: {{message}}', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\", \"product_category\": \"Product Category\",\"review_time\":\"Time when reviewd\", \"edit_url\": \"Edit URL\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 0, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 11:58:01'),
(34, 'PRODUCT_UPDATE_APPROVED', 'Product update approved', 'Your update approved', NULL, 'Hello&nbsp;{{author}},<div><b>{{product_name}} </b>, in&nbsp;{{product_category}} update is approved at&nbsp;{{review_time}}.&nbsp;<br></div><div>Reviewer message:&nbsp;{{message}}</div>', 'adfasdf', NULL, '{\"author\": \"Author username\", \"product_name\":\"Name of the product\", \"product_category\": \"Product Category\",\"review_time\":\"Time when reviewd\", \"url\": \"URL\", \"message\": \"Message from reviewer\"}', 1, NULL, NULL, 1, NULL, 0, '2021-11-03 12:00:00', '2024-01-10 08:04:35');
